'use strict'

// Thin wrapper over the napi-rs addon (binding.js, generated by `npm run
// build`). It adds the two things napi-rs cannot express natively: AbortSignal
// support and `error.code`.

const native = require('./binding.js')

// The addon prefixes failures with their class, e.g.
// "ERR_INL_TIMEOUT: inference timeout: ...".
const CODE_PREFIX = /^(ERR_INL[A-Z_]*): /

function withCode(error) {
  if (error instanceof Error) {
    const match = CODE_PREFIX.exec(error.message)
    if (match) {
      error.code = match[1]
      error.message = error.message.slice(match[0].length)
    }
  }
  return error
}

/** Runs `work(abortHandle?)`, honouring an optional AbortSignal. */
async function call(run, signal) {
  signal?.throwIfAborted()
  if (!signal) {
    try {
      return await run(undefined)
    } catch (error) {
      throw withCode(error)
    }
  }
  const handle = new native.AbortHandle()
  const onAbort = () => handle.abort()
  signal.addEventListener('abort', onAbort, { once: true })
  try {
    return await run(handle)
  } catch (error) {
    if (signal.aborted) throw signal.reason
    throw withCode(error)
  } finally {
    signal.removeEventListener('abort', onAbort)
  }
}

class TextEmbedder {
  #inner

  /** @param {import('./index').TextEmbedderOptions} [options] */
  constructor(options) {
    try {
      this.#inner = new native.TextEmbedder(options)
    } catch (error) {
      throw withCode(error)
    }
  }

  /** @param {import('./index').CallOptions} [options] */
  identity() {
    return call(() => this.#inner.identity())
  }

  /** @param {import('./index').CallOptions} [options] */
  embed(texts, options) {
    return call((abort) => this.#inner.embed(texts, abort), options?.signal)
  }

  /** @param {import('./index').CallOptions} [options] */
  embedQuery(text, options) {
    return call((abort) => this.#inner.embedQuery(text, abort), options?.signal)
  }

  get isLoaded() {
    return this.#inner.isLoaded()
  }

  unload() {
    return this.#inner.unload()
  }

  dispose() {
    return this.#inner.dispose()
  }
}

class SparseEncoder {
  #inner

  /** @param {import('./index').SparseEncoderOptions} [options] */
  constructor(options) {
    try {
      this.#inner = new native.SparseEncoder(options)
    } catch (error) {
      throw withCode(error)
    }
  }

  identity() {
    return call(() => this.#inner.identity())
  }

  /** @param {import('./index').CallOptions} [options] */
  encode(texts, options) {
    return call((abort) => this.#inner.encode(texts, abort), options?.signal)
  }

  /** @param {import('./index').CallOptions} [options] */
  encodeQuery(text, options) {
    return call((abort) => this.#inner.encodeQuery(text, abort), options?.signal)
  }

  get isLoaded() {
    return this.#inner.isLoaded()
  }

  unload() {
    return this.#inner.unload()
  }
}

class Daemon {
  #inner

  constructor(inner) {
    this.#inner = inner
  }

  /**
   * @param {import('./index').EngineOptions} engineOptions
   * @param {import('./index').ServerOptions} [serverOptions]
   * @returns {Promise<Daemon>}
   */
  static spawn(engineOptions, serverOptions) {
    return native.Daemon.spawn(engineOptions, serverOptions ?? {}).then(
      (inner) => new Daemon(inner),
      (error) => {
        throw withCode(error)
      },
    )
  }

  url() {
    return this.#inner.url()
  }

  health() {
    return this.#inner.health()
  }

  async stop() {
    try {
      return await this.#inner.stop()
    } catch (error) {
      throw withCode(error)
    }
  }

  async wait() {
    try {
      return await this.#inner.wait()
    } catch (error) {
      throw withCode(error)
    }
  }
}

class DaemonClient {
  #inner

  constructor(inner) {
    this.#inner = inner
  }

  /** @param {import('./index').DiscoverOptions} options */
  static discover(options) {
    const inner = native.DaemonClient.discover(options)
    return inner ? new DaemonClient(inner) : null
  }

  url() {
    return this.#inner.url()
  }

  async health() {
    return this.#inner.health()
  }

  async waitReady(timeoutMs) {
    try {
      return await this.#inner.waitReady(timeoutMs)
    } catch (error) {
      throw withCode(error)
    }
  }

  async stop() {
    try {
      await this.#inner.stop()
    } catch (error) {
      throw withCode(error)
    }
  }

  async unload() {
    try {
      return await this.#inner.unload()
    } catch (error) {
      throw withCode(error)
    }
  }
}

module.exports = { TextEmbedder, SparseEncoder, Daemon, DaemonClient }
